using System;
using System.Linq.Expressions;

// PROGRAM: Menginspeksi Expression Tree secara Dinamis
// 1. Delegate Biasa (Black Box: Tidak bisa dibongkar rumusnya)
Func<int, bool> funcBiasa = n => n > 100;
Console.WriteLine($"Eksekusi Func Biasa: {funcBiasa(150)}");

// 2. Expression Tree (Data Struktur Terbuka: Dapat dibongkar rumusnya)
Expression<Func<int, bool>> pohonEkspresi = n => n > 100;

Console.WriteLine("\n=== MEMBONGKAR ANATOMI EXPRESSION TREE ===");
Console.WriteLine($"Tipe Node Root : {pohonEkspresi.NodeType}"); // Lambda
Console.WriteLine($"Tipe Kembalian : {pohonEkspresi.ReturnType}");

if (pohonEkspresi.Body is BinaryExpression binary)
{
    Console.WriteLine($"Operator Biner : {binary.NodeType}"); // GreaterThan
    Console.WriteLine($"Sisi Kiri      : {binary.Left}");     // n
    Console.WriteLine($"Sisi Kanan     : {binary.Right}");    // 100

    // Inilah cara EF Core menerjemahkan ekspresi C# menjadi SQL 'WHERE n > 100'!
}

