using System;
using System.Linq.Expressions;

public class DynamicExpressionBuilder
{
    public static Expression<Func<int, bool>> CreateGreaterThanExpression(int threshold)
    {
        var param = Expression.Parameter(typeof(int), "x");
        var constant = Expression.Constant(threshold, typeof(int));
        var body = Expression.GreaterThan(param, constant);

        return Expression.Lambda<Func<int, bool>>(body, param);
    }

    public static void Main()
    {
        var expr = CreateGreaterThanExpression(50);
        var compiled = expr.Compile();

        Console.WriteLine($"75 > 50: {compiled(75)}");
        Console.WriteLine($"25 > 50: {compiled(25)}");
    }
}
